ctl.submit.anchorText:
export async function onSubmit(form: LoginForm): Promise<LoginResult> {
  const problem = validateForm(form);
  if (problem) return showError(problem);

  const result = await authenticate(form.username, form.password);
  if (!result.ok) return showError(result.reason);

  return routeAfterLogin(result.user);
}

ctl.error.anchorText:
function showError(message: string): LoginResult {
  console.warn(`[login] ${message}`);
  return { error: message };
}

val.record.anchorText:
export function recordFailure(username: string): void {
  failures.set(username, (failures.get(username) ?? 0) + 1);
}

auth.request.anchorText:
const token = await requestToken(username, password);
if (typeof token !== 'string') {
  recordFailure(username);
  return { ok: false, reason: token.reason };
}

auth.profile.anchorText:
async function loadProfile(token: string): Promise<User> {
  const response = await fetch('/api/me', { headers: { authorization: `Bearer ${token}` } });
  return (await response.json()) as User;
}

req.post.anchorText:
for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
  const response = await fetch('/api/login', {
    method: 'POST',
    body: JSON.stringify({ username, password }),
  });

route.fn.anchorText:
export function routeAfterLogin(user: User): LoginResult {
  if (user.mustChangePassword) return { page: '/account/password' };
  if (user.firstLogin) return { page: '/onboarding' };
  return { page: redirectTarget() ?? '/home' };
}

route.redirect.anchorText:
function redirectTarget(): string | undefined {
  const target = new URLSearchParams(location.search).get('redirect');
  return target?.startsWith('/') ? target : undefined;
}
